#!/usr/bin/env python3
"""Publish every Gazebo result, including terminal fault and teardown overlap."""
import gzip,hashlib,json,math,os,subprocess
from pathlib import Path
for key in ['OMP_NUM_THREADS','OPENBLAS_NUM_THREADS','MKL_NUM_THREADS']:os.environ[key]='1'
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.patches import Rectangle,Circle
HERE=Path(__file__).resolve().parent;REPO=HERE.parents[3];REPORTS=HERE/'reports';load=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
plan=load(HERE/'protocol.json');execution=load(REPORTS/'execution.json');assert len(execution)==9
assert all(row['audit_exit_code']==0 for row in execution),execution
rows=[]
for row in execution:
    out=REPO/row['report'];v=load(out/'validation.json');result=load(out/'result.json');assert v['model']==row['model'] and v['case']==row['case']
    rows.append(dict(**v,report=str(out.relative_to(HERE)),run_status=result['status'],command=row['command']))
(REPORTS/'summary.json').write_text(json.dumps(rows,indent=2)+'\n')
# Plot only measured SceneBroadcaster poses up to the assessment end; no inferred trajectories.
fig,axes=plt.subplots(3,3,figsize=(15,11));boxes=load(HERE.parent/'common_response/inputs/layout.json')['obstacles'];labels={'soc_guarded_orca':'SocNavGym guarded','crowd_orca_plus':'CrowdSimPlus ORCA+','complex_geometry_mixed':'ComplexityNav geometry'}
limits={'crossing_near':(-29,-18,-4,4),'opposed_near':(-28,-14,-4,4),'blocked_narrow_near':(6,28,-4,4)}
for ci,case in enumerate(plan['cases']):
    for mi,model in enumerate(plan['models']):
        row=next(v for v in rows if v['case']==case and v['model']==model);out=HERE/row['report'];ax=axes[ci,mi]
        with gzip.open(out/'gazebo_poses.jsonl.gz','rt') as f:poses=[json.loads(line) for line in f]
        poses=[p for p in poses if p['time']<=row['assessment_end_sim']+1e-8 and len(p['poses'])==7]
        for b in boxes:ax.add_patch(Rectangle((b['x']-b['sx']/2,b['y']-b['sy']/2),b['sx'],b['sy'],fc='#c5cbd2',ec='#929ca6',lw=.4))
        for hid in range(1,7):
            name=f'common_{hid}_proxy';x=[p['poses'][name]['x'] for p in poses];y=[p['poses'][name]['y'] for p in poses];color=f'C{hid-1}'
            ax.plot(x,y,color=color,lw=1.5);ax.add_patch(Circle((x[0],y[0]),.36,ec=color,fc='none',lw=.8));ax.plot(x[-1],y[-1],'o',color=color,ms=3)
        x=[p['poses']['mecanum_robot']['x'] for p in poses];y=[p['poses']['mecanum_robot']['y'] for p in poses];ax.plot(x,y,'k--',lw=1.7,label='Robot');ax.plot(x[0],y[0],'ks',ms=4)
        x0,x1,y0,y1=limits[case];ax.set(xlim=(x0,x1),ylim=(y0,y1),aspect='equal',xlabel='x [m]',ylabel='y [m]');ax.grid(alpha=.15)
        suffix='ERROR at5.5s' if row['run_status']=='ERROR' else '10s complete';ax.set_title(labels[model]+' | '+case+'\n'+suffix,fontsize=9,color='#b52222' if row['run_status']=='ERROR' else '#222222')
fig.suptitle('Actual Gazebo poses |6 humans, radius0.36m |1 seed | Near conditions only',fontsize=13);fig.tight_layout(rect=[0,0,1,.96]);fig.savefig(REPORTS/'actual_trajectories.png',dpi=130);plt.close(fig)
lines=['# Benchmark chung Gazebo — kết quả và giới hạn','', 'Ngày22/10/2026. Bộ offline đã commit **`ff79dbf`** (`feat: benchmark shared offline social navigation scenarios`). Cohort này dùng6 người, radius0.36m,42 vật cản nhà xưởng và robot Mecanum thật trong Gazebo; robot nhận cùng lệnh vận tốc theo thời gian, worker nhận pose/velocity đo thực. **Chưa bật Nav2; formation tắt trong cohort avoidance này.**','', f"Đã thực hiện9/9 lượt: **{sum(v['run_status']=='RECORDED' for v in rows)} hoàn tất**, **{sum(v['run_status']=='ERROR' for v in rows)} lỗi terminal**. Không retry hoặc thay lượt lỗi bằng lượt khác. Toàn bộ9 lượt có dữ liệu actual pose/LiDAR/camera, renderer NVIDIA và shutdown/cleanup được kiểm tra. Audit dữ liệu một prefix lỗi không có nghĩa lượt đó đạt nghiệm thu.",'','| Cấu hình | Cảnh | Thực thi | Gap người–người | Gap robot–người | Gap vật cản | LiDAR khớp<15cm |','|---|---|---|---:|---:|---:|---:|']
for v in rows:
    g=v['actual_swept_gap_m'];lines.append(f"|{labels[v['model']]}|{v['case']}|{'Lỗi tại5.5s' if v['run_status']=='ERROR' else 'Đủ10s'}|{g['pair']:.4f}m|{g['robot']:.4f}m|{g['static']:.4f}m|{100*v['lidar_within_15cm_fraction']:.2f}%|")
lines += ['', 'Signed gaps dùng actual SceneBroadcaster poses, closest-relative-approach và GEOS segment-to-box độc lập; không lấy command pose làm actual. Bảng giới hạn0..10s theo phase worker; prefix lỗi dừng tại thời điểm fault. Ngưỡng gắn nhãn overlap là5mm; mọi minima thô vẫn giữ, không phải chứng minh an toàn liên tục giữa mọi physics tick. Nominal robot disc radius0.25m không thay cho mọi chi tiết robot/mesh cơ thể. Lidar chỉ tính các tia dự đoán trúng proxy người gần hơn42 boxes, trong range hợp lệ; tỷ lệ này không phải recall toàn bộ người/cảnh. IDs cụ thể lưu từng validation.json.','', '![Quỹ đạo đo từ Gazebo](actual_trajectories.png)','', '## Lỗi SocNavGym phải xử lý trước Nav2','', 'Ở `soc_crossing01`, worker dừng terminal tại5.5025s sau55 update. Bộ33 tỷ lệ của một đề xuất ORCA không tìm được phương án đạt clearance2mm khi giữ vận tốc robot đo thực. Đây là giới hạn của họ đề xuất đang thử, không phải chứng minh mọi chuyển động người đều bất khả thi. [Audit source](soc_failure_source_audit.json) mô tả đúng phạm vi; native/vendor/guard đã đo không được sửa để làm đẹp kết quả.','', 'Đến trước fault, khoảng hở robot–người nhỏ nhất còn **+5.12mm**. Trong phần kết thúc phiên, người bị giữ tại pose cuối trong khi robot tiếp tục trôi; toàn recording có gap **−10.83cm**. Đó là một lỗi vận hành cần sửa, không được loại khỏi báo cáo dù bảng cửa sổ tiền fault còn dương. Recorder hiện kết thúc server khi callback báo lỗi; chưa có xác nhận dừng robot tức thời hoặc bảo đảm khoảng dừng. Dữ liệu này không được dùng làm demo tự chạy an toàn.','', '![Gazebo camera thật — SocNavGym prefix lỗi,4×](soc_crossing01/camera_preview_4x.gif)','', '![Gazebo camera thật — CrowdSimPlus ORCA+,4×](crowd_crossing01/camera_preview_4x.gif)','', '![Gazebo camera thật — ComplexityNav geometry,4×](complex_crossing01/camera_preview_4x.gif)','', 'Camera lưu1frame/s,640×480, quantize khi đóng GIF, phát4×. Đây là RGB camera Gazebo đã chạy, không phải AI hoặc hoạt cảnh tự dựng. Hình quỹ đạo ở trên là đồ thị dữ liệu đo, không phải ảnh camera. GUI được mở ở lượt Soc crossing; chưa có xác nhận thao tác GUI riêng cho cohort này. Các xác nhận kéo/zoom các pilot trước giữ riêng.','', '## So sánh được đến đâu','', 'Ba cấu hình dùng cùng initial fixture/targets/radius/geometry và velocity script cho3 near scenes. Native dt0.1s(Soc/CSP),0.25s(CN), native intended speed/observation buffers khác nhau. Worker mới dùng nguyên lớp Runner offline đóng băng, không chép lại thuật toán; IPC thật đã khớp exact20 bước đầu dữ liệu offline cho cả3 và đóng terminal khi clock sai. Một test harness đầu tiên thiếu omega bị worker từ chối trước update0, giữ ở transport_attempt01; đã sửa request test, không sửa policy. CLI transport sau đo chỉ thêm tên output mới.','', 'Gazebo có khởi động/acceleration/communication latency: cùng lệnh vận tốc không có nghĩa robot đi đúng trajectory offline hoặc robot paths ba nhánh giống hệt. Sai lệch lớn nhất giữa actual XY và scripted reference được lưu; kết quả near/far offline không chuyển trực tiếp thành kết luận nhân quả tại Gazebo. Trong cohort này không có far controls, multi-seed, long-run deadlock, hay navigation success benchmark.10s không yêu cầu tới goal xa. Robot đi open-loop và không nhường chủ động; actor vẫn dùng walk clip, không chứng nhận gait/hội thoại tự nhiên.','', 'Min khoảng hở dương vài cm không đủ chọn mô hình tự nhiên nhất. Khả năng nhóm đi/đứng tương tác/formation của SocNavGym dựa pilot lifecycle trước;6 người trong cohort này đi cá nhân. CrowdSimPlus ORCA+ giữ làm baseline tránh người. ComplexityNav geometry là native mixed intent + roadmap/ORCA projection, không phải native solver dùng42 boxes hay trained RGL. Không bật World Model hoặc thay kiến trúc robot.','', '## Quyết định và việc tiếp theo','', '**Giữ SocNavGym làm ứng viên chính cho nhóm, nhưng chưa nghiệm thu bản này cho giao cắt sát robot/Nav2.** CrowdSimPlus ORCA+ tiếp tục làm đối chứng độc lập. Giữ ComplexityNav geometry làm lựa chọn nghiên cứu phụ. Bước cần làm trước Nav2: bổ sung proposal né robot cho SocNavGym trong phiên bản mới và xử lý dừng robot khi worker fault, tái hiện đúng ca5.5s để đo lại; không ghi đè baseline này. Sau đó mới chạy Nav2 trên scene thống nhất, không mở rộng sang Isaac Sim/World Model trong bước hiện tại.','', '[Protocol](../protocol.json) · [9 lệnh và trạng thái](execution.json) · [Toàn bộ số đo](summary.json) · [IPC exact-prefix](transport01/validation.json). Mỗi report con chứa source/input hashes, result/validation, worker log và observations gzip byte-identical, SDF sinh riêng, ảnh/GIF. Các file source/ROS/Nav2/vendor và evidence cũ được kiểm hash; staging của người dùng được giữ.']
(REPORTS/'COMMON_GAZEBO_REPORT.md').write_text('\n'.join(lines)+'\n')
print(json.dumps(dict(attempts=len(rows),completed=sum(v['run_status']=='RECORDED' for v in rows),errors=sum(v['run_status']=='ERROR' for v in rows),max_script_error=max(v['robot_script_position_error_max_m'] for v in rows),minimum_lidar_fraction=min(v['lidar_within_15cm_fraction'] for v in rows)),indent=2))
